{
  "id": "{{prefix}}pcv",
  "name": "IDJAG Test PCV",
  "pluginDescriptorRef": {
    "id": "org.sourceid.saml20.domain.SimpleUsernamePasswordCredentialValidator"
  },
  "configuration": {
    "tables": [
      {
        "name": "Users",
        "rows": [
          {
            "fields": [
              {
                "name": "Username",
                "value": "{{test_user}}"
              },
              {
                "name": "Password",
                "value": "{{test_pass}}"
              },
              {
                "name": "Confirm Password",
                "value": "{{test_pass}}"
              },
              {
                "name": "Relax Password Requirements",
                "value": "true"
              }
            ],
            "defaultRow": false
          }
        ]
      }
    ],
    "fields": []
  },
  "attributeContract": {
    "coreAttributes": [
      {
        "name": "username"
      }
    ]
  }
}

{
  "id": "{{prefix}}form",
  "name": "IDJAG HTML Form",
  "pluginDescriptorRef": {
    "id": "com.pingidentity.adapters.htmlform.idp.HtmlFormIdpAuthnAdapter"
  },
  "configuration": {
    "tables": [
      {
        "name": "Credential Validators",
        "rows": [
          {
            "fields": [
              {
                "name": "Password Credential Validator Instance",
                "value": "{{prefix}}pcv"
              }
            ],
            "defaultRow": false
          }
        ]
      }
    ],
    "fields": [
      {
        "name": "Challenge Retries",
        "value": "3"
      },
      {
        "name": "Login Template",
        "value": "html.form.login.template.html"
      },
      {
        "name": "Logout Template",
        "value": "idp.logout.success.page.template.html"
      },
      {
        "name": "Session State",
        "value": "None"
      }
    ]
  },
  "attributeContract": {
    "coreAttributes": [
      {
        "name": "username",
        "pseudonym": true,
        "masked": false
      }
    ],
    "extendedAttributes": []
  },
  "attributeMapping": {
    "attributeSources": [],
    "attributeContractFulfillment": {
      "username": {
        "source": {
          "type": "ADAPTER"
        },
        "value": "username"
      }
    },
    "issuanceCriteria": {
      "conditionalCriteria": []
    }
  }
}

{
  "id": "{{prefix}}atm",
  "name": "IDJAG ATM",
  "pluginDescriptorRef": {
    "id": "org.sourceid.oauth20.token.plugin.impl.ReferenceBearerAccessTokenManagementPlugin"
  },
  "configuration": {
    "fields": [
      {
        "name": "Token Length",
        "value": "28"
      },
      {
        "name": "Token Lifetime",
        "value": "120"
      },
      {
        "name": "Lifetime Extension Policy",
        "value": "NONE"
      },
      {
        "name": "Lifetime Extension Threshold Percentage",
        "value": "30"
      },
      {
        "name": "Mode for Synchronous RPC",
        "value": "3"
      },
      {
        "name": "RPC Timeout",
        "value": "500"
      },
      {
        "name": "Expand Scope Groups",
        "value": "false"
      }
    ]
  },
  "attributeContract": {
    "coreAttributes": [],
    "extendedAttributes": [
      {
        "name": "sub",
        "multiValued": false
      }
    ]
  },
  "selectionSettings": {
    "resourceUris": []
  },
  "accessControlSettings": {
    "restrictClients": false,
    "allowedClients": []
  },
  "sessionValidationSettings": {
    "checkValidAuthnSession": false,
    "checkSessionRevocationStatus": false,
    "updateAuthnSessionActivity": false,
    "includeSessionId": false
  }
}

{
  "id": "{{prefix}}rasatm",
  "name": "IDJAG RAS ATM",
  "pluginDescriptorRef": {
    "id": "org.sourceid.oauth20.token.plugin.impl.ReferenceBearerAccessTokenManagementPlugin"
  },
  "configuration": {
    "fields": [
      {
        "name": "Token Length",
        "value": "28"
      },
      {
        "name": "Token Lifetime",
        "value": "120"
      },
      {
        "name": "Lifetime Extension Policy",
        "value": "NONE"
      },
      {
        "name": "Lifetime Extension Threshold Percentage",
        "value": "30"
      },
      {
        "name": "Mode for Synchronous RPC",
        "value": "3"
      },
      {
        "name": "RPC Timeout",
        "value": "500"
      },
      {
        "name": "Expand Scope Groups",
        "value": "false"
      }
    ]
  },
  "attributeContract": {
    "coreAttributes": [],
    "extendedAttributes": [
      {
        "name": "sub",
        "multiValued": false
      }
    ]
  },
  "selectionSettings": {
    "resourceUris": [
      "{{resource}}"
    ]
  },
  "accessControlSettings": {
    "restrictClients": false,
    "allowedClients": []
  },
  "sessionValidationSettings": {
    "checkValidAuthnSession": false,
    "checkSessionRevocationStatus": false,
    "updateAuthnSessionActivity": false,
    "includeSessionId": false
  }
}

{
  "id": "{{prefix}}oidc",
  "name": "IDJAG OIDC Policy",
  "accessTokenManagerRef": {
    "id": "{{prefix}}atm"
  },
  "idTokenLifetime": 5,
  "includeSriInIdToken": true,
  "includeUserInfoInIdToken": false,
  "includeSHashInIdToken": false,
  "includeX5tInIdToken": false,
  "returnIdTokenOnRefreshGrant": true,
  "reissueIdTokenInHybridFlow": false,
  "attributeContract": {
    "coreAttributes": [
      {
        "name": "sub"
      }
    ],
    "extendedAttributes": []
  },
  "attributeMapping": {
    "attributeSources": [],
    "attributeContractFulfillment": {
      "sub": {
        "source": {
          "type": "OAUTH_PERSISTENT_GRANT"
        },
        "value": "USER_KEY"
      }
    },
    "issuanceCriteria": {
      "conditionalCriteria": []
    }
  },
  "scopeAttributeMappings": {}
}

{
  "id": "{{prefix}}atp",
  "name": "IDJAG Access Token Processor",
  "pluginDescriptorRef": {
    "id": "org.sourceid.wstrust.processor.oauth.BearerAccessTokenTokenProcessor"
  },
  "configuration": {
    "fields": [
      {
        "name": "Access Token Manager",
        "value": "{{prefix}}atm"
      },
      {
        "name": "Scope value as single string",
        "value": "false"
      }
    ]
  },
  "attributeContract": {
    "coreAttributes": [
      {
        "name": "aud"
      },
      {
        "name": "authorization_details"
      },
      {
        "name": "client_id"
      },
      {
        "name": "expires_at"
      },
      {
        "name": "iss"
      },
      {
        "name": "scope"
      }
    ],
    "extendedAttributes": [
      {
        "name": "sub"
      }
    ],
    "maskOgnlValues": false
  }
}

{
  "id": "{{prefix}}itp",
  "name": "IDJAG ID Token Processor",
  "pluginDescriptorRef": {
    "id": "com.pingidentity.pf.tokenprocessors.jwt.JwtTokenProcessor"
  },
  "configuration": {
    "tables": [
      {
        "name": "Allowed Issuers",
        "rows": [
          {
            "fields": [
              {
                "name": "Issuer",
                "value": "{{issuer}}"
              },
              {
                "name": "JWKS URL",
                "value": ""
              },
              {
                "name": "JWKS",
                "value": "{{jwks_escaped}}"
              }
            ],
            "defaultRow": false
          }
        ]
      },
      {
        "name": "Allowed Audiences",
        "rows": [
          {
            "fields": [
              {
                "name": "Audience",
                "value": "{{ac_client_id}}"
              }
            ],
            "defaultRow": false
          }
        ]
      }
    ],
    "fields": [
      {
        "name": "Require Audience",
        "value": "true"
      },
      {
        "name": "Require Expiration Time",
        "value": "true"
      },
      {
        "name": "Require Issued At Time",
        "value": "false"
      },
      {
        "name": "Require Not Before Time",
        "value": "false"
      },
      {
        "name": "Default Cache Duration",
        "value": "720"
      },
      {
        "name": "Allowed Clock Skew",
        "value": "30"
      }
    ]
  },
  "attributeContract": {
    "coreAttributes": [
      {
        "name": "sub"
      }
    ],
    "extendedAttributes": [],
    "maskOgnlValues": false
  }
}

{
  "id": "{{prefix}}sp",
  "name": "IDJAG Resource AS",
  "entityId": "{{issuer}}",
  "active": true,
  "connectionTargetType": "STANDARD",
  "type": "SP",
  "loggingMode": "STANDARD",
  "credentials": {
    "signingSettings": {
      "signingKeyPairRef": {
        "id": "{{signing_key_id}}"
      },
      "algorithm": "SHA256withRSA",
      "includeCertInSignature": false,
      "includeRawKeyInSignature": false
    }
  },
  "oauthTokenExchangeSettings": {
    "resourceUris": [
      "{{resource}}"
    ],
    "idJagEnabled": true,
    "minutesBefore": 5,
    "minutesAfter": 5,
    "attributeContract": {
      "coreAttributes": [
        {
          "name": "TOKEN_SUBJECT"
        }
      ],
      "extendedAttributes": []
    },
    "processorPolicyMappings": [
      {
        "processorPolicyRef": {
          "id": "{{prefix}}policy"
        },
        "attributeSources": [],
        "attributeContractFulfillment": {
          "TOKEN_SUBJECT": {
            "source": {
              "type": "TOKEN_EXCHANGE_PROCESSOR_POLICY"
            },
            "value": "subject"
          }
        },
        "issuanceCriteria": {
          "conditionalCriteria": []
        }
      }
    ]
  }
}

{
  "id": "{{prefix}}idp",
  "name": "IDJAG Issuer",
  "type": "IDP",
  "entityId": "{{issuer}}",
  "active": true,
  "loggingMode": "STANDARD",
  "credentials": {
    "certs": [
      {
        "x509File": {
          "fileData": "{{signing_cert_b64}}"
        },
        "activeVerificationCert": true,
        "primaryVerificationCert": true,
        "secondaryVerificationCert": false,
        "encryptionCert": false
      }
    ]
  },
  "idpOAuthGrantAttributeMapping": {
    "idpOAuthAttributeContract": {
      "coreAttributes": [],
      "extendedAttributes": [
        {
          "name": "sub"
        }
      ]
    },
    "accessTokenManagerMappings": [
      {
        "accessTokenManagerRef": {
          "id": "{{prefix}}rasatm"
        },
        "attributeSources": [],
        "attributeContractFulfillment": {
          "sub": {
            "source": {
              "type": "ASSERTION"
            },
            "value": "sub"
          }
        },
        "issuanceCriteria": {
          "conditionalCriteria": []
        }
      }
    ]
  }
}

{
  "clientId": "{{ac_client_id}}",
  "name": "IDJAG Requesting App",
  "enabled": true,
  "redirectUris": [
    "{{callback_url}}",
    "https://oauth.pstmn.io/v1/browser-callback"
  ],
  "grantTypes": [
    "AUTHORIZATION_CODE",
    "REFRESH_TOKEN",
    "TOKEN_EXCHANGE",
    "RESOURCE_OWNER_CREDENTIALS"
  ],
  "clientAuth": {
    "type": "SECRET",
    "secret": "{{ac_secret}}"
  },
  "restrictScopes": false,
  "bypassApprovalPage": true,
  "defaultAccessTokenManagerRef": {
    "id": "{{prefix}}atm"
  },
  "oidcPolicy": {
    "policyGroup": {
      "id": "{{prefix}}oidc"
    },
    "idTokenSigningAlgorithm": "RS256",
    "grantAccessSessionRevocationApi": false,
    "grantAccessSessionSessionManagementApi": false,
    "pingAccessLogoutCapable": false
  },
  "tokenExchangeProcessorPolicyRef": {
    "id": "{{prefix}}policy"
  }
}

{
  "clientId": "{{introspect_client_id}}",
  "name": "IDJAG RAS Introspection Client",
  "enabled": true,
  "grantTypes": [
    "ACCESS_TOKEN_VALIDATION"
  ],
  "clientAuth": {
    "type": "SECRET",
    "secret": "{{introspect_secret}}"
  },
  "restrictScopes": false,
  "validateUsingAllEligibleAtms": true
}
